RUSTFLAGS=-Awarnings cargo test --package ripgrep --test integration -- multiline::replacement

cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('crates/printer/src/util.rs')
text = path.read_text()
old = '''    /// replacement, use the `replacement` method.
    ///
    /// This can fail if the underlying matcher reports an error.
'''
new = '''    /// replacement, use the `replacement` method.
    ///
    /// Only matches starting within `range` are replaced, and bytes outside
    /// `range` are not copied to the result. The surrounding subject remains
    /// available for resolving look-around assertions.
    ///
    /// This can fail if the underlying matcher reports an error.
'''
assert text.count(old) == 1
text = text.replace(old, new)
old = '''            matcher
                .replace_with_captures_at(
                    subject,
                    range.start,
                    caps,
                    dst,
                    |caps, dst| {
                        let start = dst.len();
                        caps.interpolate(
                            |name| matcher.capture_index(name),
                            subject,
                            replacement,
                            dst,
                        );
                        let end = dst.len();
                        matches.push(Match::new(start, end));
                        true
                    },
                )
                .map_err(io::Error::error_message)?;
'''
new = '''            let mut last_match = range.start;
            matcher
                .captures_iter_at(subject, range.start, caps, |caps| {
                    let m = caps.get(0).unwrap();
                    if is_multi_line && m.start() >= range.end {
                        return false;
                    }
                    dst.extend_from_slice(&subject[last_match..m.start()]);
                    last_match = m.end();
                    let start = dst.len();
                    caps.interpolate(
                        |name| matcher.capture_index(name),
                        subject,
                        replacement,
                        dst,
                    );
                    let end = dst.len();
                    matches.push(Match::new(start, end));
                    true
                })
                .map_err(io::Error::error_message)?;
            let end = range.end.min(subject.len());
            if last_match < end {
                dst.extend_from_slice(&subject[last_match..end]);
            }
'''
assert text.count(old) == 1
path.write_text(text.replace(old, new))
path = Path('tests/multiline.rs')
text = path.read_text()
anchor = 'rgtest!(replacement_look_ahead, |dir: Dir, mut cmd: TestCommand| {'
addition = '''rgtest!(replacement_line_end, |dir: Dir, mut cmd: TestCommand| {
    dir.create("test", "a\\nb");
    cmd.args(&["-N", "-r", "x", "$", "test"]);
    eqnice!("ax\\nbx\\n", cmd.stdout());
});

'''
assert text.count(anchor) == 1
path.write_text(text.replace(anchor, addition + anchor))
path = Path('CHANGELOG.md')
text = path.read_text()
anchor = 'Bug fixes:\n\n'
assert anchor in text
path.write_text(text.replace(anchor, anchor + '* Fix multiline replacements printing or replacing text beyond matching lines.\n', 1))
PY
