cd /testbed && python3 - <<'PY'
import subprocess
content = '''# Compile requirements.txt files from all found or specified requirements.in files (compile).
# Use -h to include hashes, -u dep1,dep2... to upgrade specific dependencies, and -U to upgrade all.
pipc () {  # [-h] [-U|-u <pkgspec>[,<pkgspec>...]] [<reqs-in>...] [-- <pip-compile-arg>...]
    emulate -L zsh
    unset REPLY
    if [[ $1 == --help ]] { zpy $0; return }
    [[ $ZPY_PROCS ]] || return

    local gen_hashes upgrade upgrade_csv
    while [[ $1 == -[hUu] ]] {
        if [[ $1 == -h ]] { gen_hashes=--generate-hashes; shift   }
        if [[ $1 == -U ]] { upgrade=1;                    shift   }
        if [[ $1 == -u ]] { upgrade=1; upgrade_csv=$2;    shift 2 }
    }
}
'''
pattern = r'^(?P<predoc>\n?(# .*\n)*)(alias (?P<aname>pipc)="[^"]+"|(?P<fname>pipc) \(\) \{)(  #(?P<usage> .+))?'
expected = ' [-h] [-U|-u <pkgspec>[,<pkgspec>...]] [<reqs-in>...] [-- <pip-compile-arg>...]\n'
for engine in [[], ['--pcre2']]:
    command = ['target/debug/rg', '--no-config', '--color', 'never', '-NU'] + engine
    original = subprocess.run(command + [pattern], input=content, text=True, capture_output=True, check=True)
    assert original.stdout == '\n'.join(content.splitlines()[:3]) + '\n', repr(original.stdout)
    for mode in [[], ['--only-matching']]:
        result = subprocess.run(command + mode + ['-r', '$usage', pattern], input=content, text=True, capture_output=True, check=True)
        assert result.stdout == expected, repr(result.stdout)
    print(('PCRE2' if engine else 'default') + ': reported example produces exactly the expected usage line')
PY
